const D = { scale: 1, density: .5, energy: .62, warp: .55, speed: 1, hue: 200, x: .5, y: .5, style: 'phase', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = 6.283185307;
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(64, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }
if (!S.rgb) S.rgb = [0, 0, 0];

// seed-deterministic singularity constellation (3 zeros + 2 poles)
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.bx = []; S.by = []; S.w = []; S.ph = []; S.rr = []; S.sign = [];
  for (let k = 0; k < 5; k++) {
    S.bx[k] = (fr(k * 4 + 1) * 2 - 1) * 0.9;
    S.by[k] = (fr(k * 4 + 2) * 2 - 1) * 0.9;
    S.w[k] = (fr(k * 4 + 3) * 0.65 + 0.14) * (fr(k * 4 + 7) > 0.5 ? 1 : -1);
    S.ph[k] = fr(k * 4 + 4) * TAU;
    S.rr[k] = 0.45 + fr(k * 4 + 5) * 0.6;
    S.sign[k] = k < 3 ? 1 : -1;
  }
  S.hoff = fr(99);
}

// hsv (h,s,v in 0..1) -> out[3] in 0..1, no per-pixel allocation
function hsv(h, s, v, out) {
  h = h - Math.floor(h);
  const i = Math.floor(h * 6), f = h * 6 - i;
  const p = v * (1 - s), q = v * (1 - f * s), u = v * (1 - (1 - f) * s);
  switch (i % 6) {
    case 0: out[0] = v; out[1] = u; out[2] = p; break;
    case 1: out[0] = q; out[1] = v; out[2] = p; break;
    case 2: out[0] = p; out[1] = v; out[2] = u; break;
    case 3: out[0] = p; out[1] = q; out[2] = v; break;
    case 4: out[0] = u; out[1] = p; out[2] = v; break;
    default: out[0] = v; out[1] = p; out[2] = q; break;
  }
}

const t = K.t;
const sec = K.section || 0, inten = K.intensity != null ? K.intensity : .6;
const spin = t * (0.10 + P.speed * 0.16) + A.lowmid * 0.6;          // continuous phase-wheel rotation (motion floor)
const expo = 0.62 + P.energy * 0.7 + inten * 0.22 + A.rms * 0.5;
const zoom = 0.4 + P.scale * 1.1;
const spanH = 2.4 / zoom;
const asp = BW / BH;
const cx = (P.x - 0.5) * 2.6, cy = (P.y - 0.5) * 2.6;
const orbitR = 0.14 + P.warp * 0.5 + A.bass * 0.15;
const ringFreq = (0.5 + P.density * 2.0) * (0.75 + 0.55 * inten);   // contour ring density (builds with intensity)
const raySect = Math.round(6 + P.density * 12);
const hueBase = P.hue / 360 + S.hoff + sec * 0.05 + t * 0.006;      // slow palette drift + per-section step
const style = P.style;

// moving singularity positions this frame
const Px = [], Py = [];
for (let k = 0; k < 5; k++) {
  const R = orbitR * S.rr[k];
  Px[k] = S.bx[k] + R * Math.cos(t * S.w[k] + S.ph[k]);
  Py[k] = S.by[k] + R * Math.sin(t * S.w[k] + S.ph[k]);
}

const g = S.g; g.loadPixels(); const px = g.pixels; const RGB = S.rgb;
for (let j = 0; j < BH; j++) {
  const zy = cy + (j / BH - 0.5) * 2 * spanH;
  for (let i = 0; i < BW; i++) {
    const zx = cx + (i / BW - 0.5) * 2 * spanH * asp;
    // f(z) = prod (z - c_k)^sign_k  ->  log|f| = sum sign*0.5*log|dz|^2 ,  arg f = sum sign*atan2
    let sl = 0, sa = 0;
    for (let k = 0; k < 5; k++) {
      const dx = zx - Px[k], dy = zy - Py[k];
      const d2 = dx * dx + dy * dy + 1e-4;
      const sg = S.sign[k];
      sl += sg * 0.5 * Math.log(d2);
      sa += sg * Math.atan2(dy, dx);
    }
    sa += spin;
    const mag = sl;
    const lev = 0.5 + 0.5 * Math.tanh(mag * 0.32);            // 0=near zero (dark) .. 1=near pole (bright)
    const rn = mag * ringFreq; const ring = rn - Math.floor(rn);
    const argn = sa / TAU; const hphase = argn - Math.floor(argn);
    const rayn = argn * raySect; const ray = rayn - Math.floor(rayn);
    const ringMesh = (0.72 + 0.28 * ring) * (0.86 + 0.14 * ray);
    let r, gg, b;
    if (style === 'thermal') {
      let heat = (0.5 + 0.5 * Math.tanh(mag * 0.34)) * ringMesh * expo;
      heat = heat < 0 ? 0 : heat > 1 ? 1 : heat;
      r = Math.min(1, heat * 3.0);
      gg = Math.min(1, Math.max(0, heat * 3.0 - 1.0));
      b = Math.min(1, Math.max(0, heat * 3.0 - 2.0) + 0.20 * (1 - heat) * (1 - heat));
    } else if (style === 'ink') {
      const dm = Math.min(ring, 1 - ring), dr = Math.min(ray, 1 - ray);
      const ringLine = dm < 0.12 ? 1 - dm / 0.12 : 0;
      const rayLine = dr < 0.10 ? 1 - dr / 0.10 : 0;
      const inkL = Math.max(ringLine, rayLine * 0.8);
      const pap = 0.90 - 0.12 * (1 - lev);
      const vv = pap * (1 - 0.92 * inkL);
      r = vv * 0.99; gg = vv * 0.955; b = vv * 0.86;
    } else if (style === 'neon') {
      const dm = Math.min(ring, 1 - ring), dr = Math.min(ray, 1 - ray);
      const ringLine = dm < 0.11 ? 1 - dm / 0.11 : 0;
      const rayLine = dr < 0.09 ? 1 - dr / 0.09 : 0;
      const glow = Math.min(1, (ringLine * 1.0 + rayLine * 0.55) * (0.45 + 0.55 * lev) * expo * 1.5);
      const vv = Math.max(0.05 + 0.08 * lev, glow);
      hsv(hphase + hueBase, 0.9, vv, RGB); r = RGB[0]; gg = RGB[1]; b = RGB[2];
    } else if (style === 'pastel') {
      const v = Math.min(1, (0.70 + 0.22 * lev) * (0.92 + 0.08 * ring) * Math.min(1.1, expo));
      const s = Math.min(0.5, (0.24 + 0.16 * ring) * (0.8 + 0.3 * lev));
      hsv(hphase + hueBase, s, v, RGB); r = RGB[0]; gg = RGB[1]; b = RGB[2];
    } else { // phase (default enhanced phase portrait)
      const v = Math.min(1, (0.28 + 0.72 * lev) * ringMesh * expo);
      const s = Math.max(0.28, Math.min(0.95, 0.86 - Math.max(0, lev - 0.72) * 2.2));
      hsv(hphase + hueBase, s, v, RGB); r = RGB[0]; gg = RGB[1]; b = RGB[2];
    }
    const o = 4 * (j * BW + i);
    px[o] = r < 0 ? 0 : r > 1 ? 255 : r * 255;
    px[o + 1] = gg < 0 ? 0 : gg > 1 ? 255 : gg * 255;
    px[o + 2] = b < 0 ? 0 : b > 1 ? 255 : b * 255;
    px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio-reactive bass bloom on top (partial, zero during validation -> baseline carries motion)
if (A.bass > 0.02 || A.rms > 0.02) {
  push(); blendMode(ADD); noStroke();
  const gl = (A.bass * 0.5 + A.rms * 0.4) * P.energy;
  fill((P.hue + 40) % 360, 40, 100, gl * 20);
  ellipse(width * 0.5, height * 0.5, width * 1.25, height * 1.25);
  blendMode(BLEND); pop();
}
